// 实现 RSA 解密 (基于 BigInt)
function base64UrlToBigInt(str) {
  let b64 = str.replace(/-/g, '+').replace(/_/g, '/');
  while (b64.length % 4) b64 += '=';
  const buf = Buffer.from(b64, 'base64');
  let hex = buf.toString('hex');
  return BigInt('0x' + hex);
}

function modPow(b, e, m) {
  let res = 1n;
  b = b % m;
  while (e > 0n) {
    if (e % 2n === 1n) res = (res * b) % m;
    e = e / 2n;
    b = (b * b) % m;
  }
  return res;
}

function rsaDecryptBlock(cBytes, jwk) {
  const c = BigInt('0x' + Buffer.from(cBytes).toString('hex'));
  let m;
  if (jwk.p && jwk.q && jwk.dp && jwk.dq && jwk.qi) {
    const p = base64UrlToBigInt(jwk.p);
    const q = base64UrlToBigInt(jwk.q);
    const dp = base64UrlToBigInt(jwk.dp);
    const dq = base64UrlToBigInt(jwk.dq);
    const qi = base64UrlToBigInt(jwk.qi);

    const m1 = modPow(c % p, dp, p);
    const m2 = modPow(c % q, dq, q);
    let h = (qi * (m1 - m2)) % p;
    if (h < 0n) h += p;
    m = m2 + h * q;
  } else {
    const n = base64UrlToBigInt(jwk.n);
    const d = base64UrlToBigInt(jwk.d);
    m = modPow(c, d, n);
  }

  let hex = m.toString(16);
  if (hex.length % 2 !== 0) hex = '0' + hex;
  let buf = Buffer.from(hex, 'hex');
  if (buf.length < 256) {
    const pad = Buffer.alloc(256 - buf.length, 0);
    buf = Buffer.concat([pad, buf]);
  }
  return buf;
}

function parsePkcs1Padding(buf) {
  // 必须以 00 02 开头，找第一个 00，后面为数据
  if (buf[0] !== 0 || buf[1] !== 2) {
    throw new Error('Invalid PKCS1 padding header: ' + buf[0] + ' ' + buf[1]);
  }
  let idx = 2;
  while (idx < buf.length && buf[idx] !== 0) {
    idx++;
  }
  if (idx >= buf.length) {
    throw new Error('No null byte found in PKCS1 padding');
  }
  return buf.slice(idx + 1);
}

// 响应解密函数
function decryptResponse(bodyText, rsaJwk) {
  const parts = bodyText.trim().split('.');
  if (parts.length !== 2) {
    throw new Error('Invalid response format: ' + bodyText.slice(0, 100));
  }
  const rsaCipherBuf = Buffer.from(parts[0], 'base64');
  const decryptedBuf = rsaDecryptBlock(rsaCipherBuf, rsaJwk);
  const aesKeyBuf = parsePkcs1Padding(decryptedBuf);
  const aesKeyStr = aesKeyBuf.toString('ascii'); // 16 字节 ASCII key

  // IV = aesKey 字节反转
  const ivBuf = Buffer.from(aesKeyBuf).reverse();

  // AES-128-CBC 解密
  const cipherWords = CryptoJS.enc.Base64.parse(parts[1]);
  const keyWords = CryptoJS.enc.Utf8.parse(aesKeyStr);
  const ivWords = CryptoJS.enc.Latin1.parse(ivBuf.toString('latin1'));

  const decrypted = CryptoJS.AES.decrypt(
    { ciphertext: cipherWords },
    keyWords,
    { iv: ivWords, mode: CryptoJS.mode.CBC, padding: CryptoJS.pad.Pkcs7 }
  );

  const jsonStr = decrypted.toString(CryptoJS.enc.Utf8);
  return JSON.parse(jsonStr);
}

// 请求签名与 Header 构造
function makeRequestHeaders(ts) {
  const plainText = `1.4.4-${ts}-3-1.0.0-win32`;
  const base64Plain = CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse(plainText));
  const keyWords = CryptoJS.enc.Utf8.parse(constants.authKey);
  const ivWords = CryptoJS.enc.Utf8.parse(constants.authIv);

  const encrypted = CryptoJS.AES.encrypt(base64Plain, keyWords, {
    iv: ivWords,
    mode: CryptoJS.mode.CBC,
    padding: CryptoJS.pad.Pkcs7
  });
  const authVal = CryptoJS.enc.Base64.stringify(encrypted.ciphertext);

  return {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
    'X-VERSION': constants.apiVersion,
    'APPID': constants.appid,
    'system': constants.system,
    'requrl': 'origin',
    'ts': ts,
    'Authentication': authVal
  };
}

async function requestApi(pathAndQuery) {
  const ts = Date.now().toString();
  const headers = makeRequestHeaders(ts);
  const url = constants.origin + pathAndQuery;

