const fs = require('fs');

// 测试纯 JS（不依赖 Buffer）实现 base64/hex/BigInt 与 PKCS1 padding 解析
function b64ToBytes(b64) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  b64 = b64.replace(/-/g, '+').replace(/_/g, '/');
  while (b64.length % 4) b64 += '=';
  const bytes = [];
  let buffer = 0, bits = 0;
  for (let i = 0; i < b64.length; i++) {
    const c = b64[i];
    if (c === '=') break;
    const val = chars.indexOf(c);
    if (val === -1) continue;
    buffer = (buffer << 6) | val;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes.push((buffer >> bits) & 0xff);
    }
  }
  return bytes;
}

function bytesToHex(bytes) {
  return bytes.map(b => b.toString(16).padStart(2, '0')).join('');
}

function base64UrlToBigInt(str) {
  const bytes = b64ToBytes(str);
  const hex = bytesToHex(bytes);
  return BigInt('0x' + hex);
}

function modPow(b, e, m) {
  let res = 1n;
  b = b % m;
  while (e > 0n) {
    if (e % 2n === 1n) res = (res * b) % m;
    e = e / 2n;
    b = (b * b) % m;
  }
  return res;
}

function rsaDecryptBlockPure(cBytes, jwk) {
  const cHex = bytesToHex(cBytes);
  const c = BigInt('0x' + cHex);
  let m;
  if (jwk.p && jwk.q && jwk.dp && jwk.dq && jwk.qi) {
    const p = base64UrlToBigInt(jwk.p);
    const q = base64UrlToBigInt(jwk.q);
    const dp = base64UrlToBigInt(jwk.dp);
    const dq = base64UrlToBigInt(jwk.dq);
    const qi = base64UrlToBigInt(jwk.qi);

    const m1 = modPow(c % p, dp, p);
    const m2 = modPow(c % q, dq, q);
    let h = (qi * (m1 - m2)) % p;
    if (h < 0n) h += p;
    m = m2 + h * q;
  } else {
    const n = base64UrlToBigInt(jwk.n);
    const d = base64UrlToBigInt(jwk.d);
    m = modPow(c, d, n);
  }

  let hex = m.toString(16);
  if (hex.length % 2 !== 0) hex = '0' + hex;
  const rawBytes = [];
  for (let i = 0; i < hex.length; i += 2) {
    rawBytes.push(parseInt(hex.substr(i, 2), 16));
  }
  const bytes = [];
  while (bytes.length + rawBytes.length < 256) {
    bytes.push(0);
  }
  return bytes.concat(rawBytes);
}

function parsePkcs1PaddingPure(bytes) {
  if (bytes[0] !== 0 || bytes[1] !== 2) {
    throw new Error('Invalid PKCS1 padding header: ' + bytes[0] + ' ' + bytes[1]);
  }
