  else if (urlLower.indexOf(".m3u8") !== -1) mediaType = "hls";
  else if (urlLower.indexOf(".flv") !== -1) mediaType = "flv";

  return {
    url: playUrl,
    name: ((playAddr.desc || "") + " " + (playAddr.title || "")).trim(),
    type: mediaType,
    bitrate: Number(playAddr.bitrate) || 0,
    width: Number(playAddr.width) || 0,
